// Core bech32 encoding/decoding (BIP173), ported from the Python reference.
const CHARSET = 'qpzry9x8gf2tvdw0s3jn54khce6mua7l';
const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];

function bech32Polymod(values) {
  let chk = 1;
  for (const v of values) {
    const b = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      chk ^= ((b >> i) & 1) ? GEN[i] : 0;
    }
  }
  return chk;
}

function bech32HrpExpand(s) {
  const out = [];
  for (const c of s) out.push(c.charCodeAt(0) >> 5);
  out.push(0);
  for (const c of s) out.push(c.charCodeAt(0) & 31);
  return out;
}

function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod(bech32HrpExpand(hrp).concat(data)) === 1;
}

// Returns [hrp, dataWithoutChecksum] or [null, null].
export function bech32Decode(bech) {
  let hasLower = false;
  let hasUpper = false;
  for (const c of bech) {
    const o = c.charCodeAt(0);
    if (o < 33 || o > 126) return [null, null];
    if (o >= 97 && o <= 122) hasLower = true;
    if (o >= 65 && o <= 90) hasUpper = true;
  }
  if (hasLower && hasUpper) return [null, null];
  bech = bech.toLowerCase();
  const pos = bech.lastIndexOf('1');
  if (pos < 1 || pos + 7 > bech.length || bech.length > 90) return [null, null];
  const data = [];
  for (let i = pos + 1; i < bech.length; i++) {
    const idx = CHARSET.indexOf(bech[i]);
    if (idx === -1) return [null, null];
    data.push(idx);
  }
  const hrp = bech.slice(0, pos);
  if (!bech32VerifyChecksum(hrp, data)) return [null, null];
  return [hrp, data.slice(0, -6)];
}

