// Segwit address decoding, ported from the Python reference (segwit_addr.py).
import { bech32Decode } from './bech32core.mjs';

// General power-of-2 base conversion, ported verbatim from the Python
// convertbits(). `data` is a plain array of numbers. Returns an array of
// numbers, or null on invalid input / padding errors.
export function convertbits(data, frombits, tobits, pad = true) {
  let acc = 0;
  let bits = 0;
  const ret = [];
  const maxv = (1 << tobits) - 1;
  const maxAcc = (1 << (frombits + tobits - 1)) - 1;
  for (const value of data) {
    if (value < 0 || (value >> frombits)) return null;
    acc = ((acc << frombits) | value) & maxAcc;
    bits += frombits;
    while (bits >= tobits) {
      bits -= tobits;
      ret.push((acc >> bits) & maxv);
    }
  }
  if (pad) {
    if (bits) {
      ret.push((acc << (tobits - bits)) & maxv);
    }
  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) {
    return null;
  }
  return ret;
}

// Decodes a segwit address. Returns [witver, witprog] on success, where
// witprog is a plain array of numbers, or [null, null] on failure.
export function decode(hrp, addr) {
  const [hrpgot, data] = bech32Decode(addr);
  if (hrpgot !== hrp) return [null, null];
  const decoded = convertbits(data.slice(1), 5, 8, false);
  if (decoded === null || decoded.length < 2 || decoded.length > 40) {
    return [null, null];
  }
  if (data[0] > 16) return [null, null];
  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
    return [null, null];
  }
  return [data[0], decoded];
}

