// Minimal argparse-compatible CLI parser for a parser with:
//   parser.add_argument('--a', type=str, required=True)
//   parser.add_argument('--b', type=str, required=True)
// plus the implicit -h/--help. Replicates the relevant CPython argparse
// behaviors: '--opt value' and '--opt=value' forms, unambiguous long-option
// prefix abbreviation, last-occurrence-wins, error messages on stderr with
// exit code 2, help on stdout with exit code 0.

const LONG_OPTIONS = ['--help', '--a', '--b'];
const REQUIRED = ['--a', '--b'];

// argparse's _negative_number_matcher; tokens matching this are values,
// not options, when no option looks like a negative number.
const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;

function isOptionLike(token) {
  return (
    token.length > 1 &&
    token[0] === '-' &&
    !NEGATIVE_NUMBER.test(token)
  );
}

function usageLine(prog) {
  return `usage: ${prog} [-h] --a A --b B\n`;
}

function errorExit(prog, message) {
  process.stderr.write(usageLine(prog));
  process.stderr.write(`${prog}: error: ${message}\n`);
  process.exit(2);
}

function printHelp(prog) {
  process.stdout.write(
    usageLine(prog) +
      '\n' +
      'options:\n' +
      '  -h, --help  show this help message and exit\n' +
      '  --a A\n' +
      '  --b B\n'
  );
  process.exit(0);
}

export function parseArgs(argv, prog) {
  const values = {};
  const leftovers = [];
  let i = 0;
  let sawDoubleDash = false;

  while (i < argv.length) {
    const token = argv[i];

    if (sawDoubleDash) {
      leftovers.push(token);
      i += 1;
      continue;
    }

    if (token === '--') {
      sawDoubleDash = true;
      i += 1;
      continue;
    }

    if (token.startsWith('--')) {
      const eq = token.indexOf('=');
      const name = eq === -1 ? token : token.slice(0, eq);
      const explicitValue = eq === -1 ? null : token.slice(eq + 1);

      // Exact match wins; otherwise unambiguous prefix abbreviation.
      let match = LONG_OPTIONS.includes(name) ? name : null;
      if (match === null) {
        const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
        if (candidates.length === 1) {
          match = candidates[0];
        } else if (candidates.length > 1) {
          errorExit(
            prog,
            `ambiguous option: ${name} could match ${candidates.join(', ')}`
          );
        }
      }

      if (match === null) {
        leftovers.push(token);
        i += 1;
        continue;
      }

      if (match === '--help') {
        printHelp(prog);
      }

      // --a / --b take exactly one argument.
      if (explicitValue !== null) {
        values[match] = explicitValue;
        i += 1;
        continue;
      }
      const next = argv[i + 1];
      if (next === undefined || isOptionLike(next)) {
        errorExit(prog, `argument ${match}: expected one argument`);
      }
      values[match] = next;
      i += 2;
      continue;
    }

    if (isOptionLike(token)) {
      if (token === '-h') {
        printHelp(prog);
      }
      leftovers.push(token);
      i += 1;
      continue;
    }

    // No positionals are defined, so any plain token is a leftover.
    leftovers.push(token);
    i += 1;
  }

  // argparse reports missing required arguments before unrecognized ones.
  const missing = REQUIRED.filter((opt) => !(opt in values));
  if (missing.length > 0) {
    errorExit(
      prog,
      `the following arguments are required: ${missing.join(', ')}`
    );
  }

  if (leftovers.length > 0) {
    errorExit(prog, `unrecognized arguments: ${leftovers.join(' ')}`);
  }

  return { a: values['--a'], b: values['--b'] };
}

