// Python-repr formatter for the decode() result tuple.
// decode() returns [witver, witprog] where each element is a number or null
// (witprog is a plain array of numbers when present). formatResult renders
// the pair exactly as Python's print() would render the 2-tuple
// (witver, witprog): None for null, integers plain, lists as [a, b, c]
// with ', ' separators, and the tuple itself as (x, y).

function pyRepr(value) {
  if (value === null) {
    return 'None';
  }
  if (Array.isArray(value)) {
    return `[${value.map(pyRepr).join(', ')}]`;
  }
  return String(value);
}

export function formatResult(result) {
  return `(${result.map(pyRepr).join(', ')})`;
}

