5	function bech32Polymod(values) {
6	  let chk = 1;
7	  for (const v of values) {
8	    const b = chk >> 25;
9	    chk = ((chk & 0x1ffffff) << 5) ^ v;
10	    for (let i = 0; i < 5; i++) {
11	      chk ^= ((b >> i) & 1) ? GEN[i] : 0;
12	    }
13	  }
14	  return chk;
15	}
16	
17	function bech32HrpExpand(s) {
18	  const out = [];
