// Low-level bech32 primitives (bech32 only, no bech32m).
// Replicates the Python reference (segwit_addr.py / bech32 v1.2.0) exactly.
// All values are plain numbers / arrays of numbers; bitwise ops stay within
// 32-bit semantics as in the Python code.

export const CHARSET = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";

export function bech32Polymod(values) {
  const GEN = [0x3b6a57b2, 0x26508e6d, 0x1ea119fa, 0x3d4233dd, 0x2a1462b3];
  let chk = 1;
  for (const v of values) {
    const b = chk >> 25;
    chk = ((chk & 0x1ffffff) << 5) ^ v;
    for (let i = 0; i < 5; i++) {
      chk ^= ((b >> i) & 1) ? GEN[i] : 0;
    }
  }
  return chk;
}

export function bech32HrpExpand(s) {
  const ret = [];
  for (let i = 0; i < s.length; i++) {
    ret.push(s.charCodeAt(i) >> 5);
  }
  ret.push(0);
  for (let i = 0; i < s.length; i++) {
    ret.push(s.charCodeAt(i) & 31);
  }
  return ret;
}

export function bech32VerifyChecksum(hrp, data) {
  return bech32Polymod(bech32HrpExpand(hrp).concat(data)) === 1;
}

export function bech32Decode(bech) {
  let allLower = true;
  let allUpper = true;
  for (let i = 0; i < bech.length; i++) {
    const c = bech.charCodeAt(i);
    if (c < 33 || c > 126) {
      return [null, null];
    }
    const ch = bech[i];
    if (ch !== ch.toLowerCase()) allLower = false;
    if (ch !== ch.toUpperCase()) allUpper = false;
  }
  if (!allLower && !allUpper) {
    return [null, null];
  }
  bech = bech.toLowerCase();
  const pos = bech.lastIndexOf('1');
  if (pos < 1 || pos + 7 > bech.length || bech.length > 90) {
    return [null, null];
  }
  const data = [];
  for (let i = pos + 1; i < bech.length; i++) {
    const idx = CHARSET.indexOf(bech[i]);
    if (idx === -1) {
      return [null, null];
    }
    data.push(idx);
  }
  const hrp = bech.slice(0, pos);
  if (!bech32VerifyChecksum(hrp, data)) {
    return [null, null];
  }
  return [hrp, data.slice(0, data.length - 6)];
}

