21	export function bech32HrpExpand(s) {
22	  const ret = [];
23	  for (let i = 0; i < s.length; i++) {
24	    ret.push(s.charCodeAt(i) >> 5);
25	  }
26	  ret.push(0);
27	  for (let i = 0; i < s.length; i++) {
28	    ret.push(s.charCodeAt(i) & 31);
