37	export function bech32Decode(bech) {
38	  let allLower = true;
39	  let allUpper = true;
40	  for (let i = 0; i < bech.length; i++) {
41	    const c = bech.charCodeAt(i);
42	    if (c < 33 || c > 126) {
43	      return [null, null];
44	    }
45	    const ch = bech[i];
46	    if (ch !== ch.toLowerCase()) allLower = false;
47	    if (ch !== ch.toUpperCase()) allUpper = false;
48	  }
49	  if (!allLower && !allUpper) {
50	    return [null, null];
51	  }
52	  bech = bech.toLowerCase();
53	  const pos = bech.lastIndexOf('1');
54	  if (pos < 1 || pos + 7 > bech.length || bech.length > 90) {
55	    return [null, null];
56	  }
57	  const data = [];
58	  for (let i = pos + 1; i < bech.length; i++) {
59	    const idx = CHARSET.indexOf(bech[i]);
60	    if (idx === -1) {
61	      return [null, null];
62	    }
63	    data.push(idx);
64	  }
65	  const hrp = bech.slice(0, pos);
66	  if (!bech32VerifyChecksum(hrp, data)) {
