1	// Segwit address decoding, ported from the Python reference (segwit_addr.py).
2	import { bech32Decode } from './bech32core.mjs';
3	
4	// General power-of-2 base conversion, ported verbatim from the Python
5	// convertbits(). `data` is a plain array of numbers. Returns an array of
6	// numbers, or null on invalid input / padding errors.
7	export function convertbits(data, frombits, tobits, pad = true) {
8	  let acc = 0;
9	  let bits = 0;
10	  const ret = [];
11	  const maxv = (1 << tobits) - 1;
12	  const maxAcc = (1 << (frombits + tobits - 1)) - 1;
13	  for (const value of data) {
14	    if (value < 0 || (value >> frombits)) return null;
15	    acc = ((acc << frombits) | value) & maxAcc;
16	    bits += frombits;
17	    while (bits >= tobits) {
18	      bits -= tobits;
19	      ret.push((acc >> bits) & maxv);
20	    }
21	  }
22	  if (pad) {
23	    if (bits) {
24	      ret.push((acc << (tobits - bits)) & maxv);
25	    }
26	  } else if (bits >= frombits || ((acc << (tobits - bits)) & maxv)) {
27	    return null;
28	  }
29	  return ret;
30	}
31	
32	// Decodes a segwit address. Returns [witver, witprog] on success, where
33	// witprog is a plain array of numbers, or [null, null] on failure.
34	export function decode(hrp, addr) {
35	  const [hrpgot, data] = bech32Decode(addr);
36	  if (hrpgot !== hrp) return [null, null];
37	  const decoded = convertbits(data.slice(1), 5, 8, false);
38	  if (decoded === null || decoded.length < 2 || decoded.length > 40) {
39	    return [null, null];
40	  }
41	  if (data[0] > 16) return [null, null];
42	  if (data[0] === 0 && decoded.length !== 20 && decoded.length !== 32) {
43	    return [null, null];
44	  }
45	  return [data[0], decoded];
46	}

1	// Python-repr formatter for the decode() result tuple.
2	// decode() returns [witver, witprog] where each element is a number or null
3	// (witprog is a plain array of numbers when present). formatResult renders
4	// the pair exactly as Python's print() would render the 2-tuple
5	// (witver, witprog): None for null, integers plain, lists as [a, b, c]
6	// with ', ' separators, and the tuple itself as (x, y).
7	
8	function pyRepr(value) {
9	  if (value === null) {
10	    return 'None';
11	  }
12	  if (Array.isArray(value)) {
13	    return `[${value.map(pyRepr).join(', ')}]`;
14	  }
15	  return String(value);
16	}
17	
18	export function formatResult(result) {
19	  return `(${result.map(pyRepr).join(', ')})`;
20	}

1	// Minimal argparse-compatible CLI parser for a parser with:
2	//   parser.add_argument('--a', type=str, required=True)
3	//   parser.add_argument('--b', type=str, required=True)
4	// plus the implicit -h/--help. Replicates the relevant CPython argparse
5	// behaviors: '--opt value' and '--opt=value' forms, unambiguous long-option
6	// prefix abbreviation, last-occurrence-wins, error messages on stderr with
7	// exit code 2, help on stdout with exit code 0.
8	
9	const LONG_OPTIONS = ['--help', '--a', '--b'];
10	const REQUIRED = ['--a', '--b'];
11	
12	// argparse's _negative_number_matcher; tokens matching this are values,
13	// not options, when no option looks like a negative number.
14	const NEGATIVE_NUMBER = /^-\d+$|^-\d*\.\d+$/;
15	
16	function isOptionLike(token) {
17	  return (
18	    token.length > 1 &&
19	    token[0] === '-' &&
20	    !NEGATIVE_NUMBER.test(token)
21	  );
22	}
23	
24	function usageLine(prog) {
25	  return `usage: ${prog} [-h] --a A --b B\n`;
26	}
27	
28	function errorExit(prog, message) {
29	  process.stderr.write(usageLine(prog));
30	  process.stderr.write(`${prog}: error: ${message}\n`);
31	  process.exit(2);
32	}
33	
34	function printHelp(prog) {
35	  process.stdout.write(
36	    usageLine(prog) +
37	      '\n' +
38	      'options:\n' +
39	      '  -h, --help  show this help message and exit\n' +
40	      '  --a A\n' +
41	      '  --b B\n'
42	  );
43	  process.exit(0);
44	}
45	
46	export function parseArgs(argv, prog) {
47	  const values = {};
48	  const leftovers = [];
49	  let i = 0;
50	  let sawDoubleDash = false;
51	
52	  while (i < argv.length) {
53	    const token = argv[i];
54	
55	    if (sawDoubleDash) {
56	      leftovers.push(token);
57	      i += 1;
58	      continue;
59	    }
60	
61	    if (token === '--') {
62	      sawDoubleDash = true;
63	      i += 1;
64	      continue;
65	    }
66	
67	    if (token.startsWith('--')) {
68	      const eq = token.indexOf('=');
69	      const name = eq === -1 ? token : token.slice(0, eq);
70	      const explicitValue = eq === -1 ? null : token.slice(eq + 1);
71	
72	      // Exact match wins; otherwise unambiguous prefix abbreviation.
73	      let match = LONG_OPTIONS.includes(name) ? name : null;
74	      if (match === null) {
75	        const candidates = LONG_OPTIONS.filter((opt) => opt.startsWith(name));
76	        if (candidates.length === 1) {
77	          match = candidates[0];
78	        } else if (candidates.length > 1) {
79	          errorExit(
80	            prog,
81	            `ambiguous option: ${name} could match ${candidates.join(', ')}`
82	          );
83	        }
84	      }
85	
86	      if (match === null) {
87	        leftovers.push(token);
88	        i += 1;
89	        continue;
90	      }
91	
92	      if (match === '--help') {
93	        printHelp(prog);
94	      }
95	
96	      // --a / --b take exactly one argument.
97	      if (explicitValue !== null) {
98	        values[match] = explicitValue;
99	        i += 1;
100	        continue;
101	      }
102	      const next = argv[i + 1];
103	      if (next === undefined || isOptionLike(next)) {
104	        errorExit(prog, `argument ${match}: expected one argument`);
105	      }
106	      values[match] = next;
107	      i += 2;
108	      continue;
109	    }
110	
111	    if (isOptionLike(token)) {
112	      if (token === '-h') {
113	        printHelp(prog);
114	      }
115	      leftovers.push(token);
116	      i += 1;
117	      continue;
118	    }
119	
120	    // No positionals are defined, so any plain token is a leftover.
121	    leftovers.push(token);
122	    i += 1;
123	  }
124	
125	  // argparse reports missing required arguments before unrecognized ones.
126	  const missing = REQUIRED.filter((opt) => !(opt in values));
127	  if (missing.length > 0) {
128	    errorExit(
129	      prog,
130	      `the following arguments are required: ${missing.join(', ')}`
131	    );
132	  }
133	
134	  if (leftovers.length > 0) {
135	    errorExit(prog, `unrecognized arguments: ${leftovers.join(' ')}`);
136	  }
137	
138	  return { a: values['--a'], b: values['--b'] };
139	}

