// Entry point, equivalent to test5.py:
//   parser.add_argument("--a", type=str, required=True)  # HRP
//   parser.add_argument("--b", type=str, required=True)  # Segwit address
//   result = bech32.decode(args.a, args.b)
//   print(result)
import path from 'node:path';
import { parseArgs } from './lib/cli.mjs';
import { decode } from './lib/segwit.mjs';
import { formatResult } from './lib/pyformat.mjs';

function main() {
  // argparse derives prog from os.path.basename(sys.argv[0]); the Node
  // equivalent is the basename of the script path (process.argv[1]).
  const prog = path.basename(process.argv[1] ?? 'test5.mjs');
  const args = parseArgs(process.argv.slice(2), prog);
  const result = decode(args.a, args.b);
  console.log(formatResult(result));
}

main();

