args.command:
cat > /tmp/fuzz.mjs <<'EOF'
const CS = "qpzry9x8gf2tvdw0s3jn54khce6mua7l";
function polymod(v){const G=[0x3b6a57b2,0x26508e6d,0x1ea119fa,0x3d4233dd,0x2a1462b3];let c=1;for(const x of v){const b=c>>25;c=((c&0x1ffffff)<<5)^x;for(let i=0;i<5;i++)c^=((b>>i)&1)?G[i]:0;}return c;}
function expand(s){const r=[];for(const ch of s)r.push(ch.charCodeAt(0)>>5);r.push(0);for(const ch of s)r.push(ch.charCodeAt(0)&31);return r;}
function conv(data,fb,tb,pad){let acc=0,bits=0;const ret=[],maxv=(1<<tb)-1,maxa=(1<<(fb+tb-1))-1;for(const v of data){acc=((acc<<fb)|v)&maxa;bits+=fb;while(bits>=tb){bits-=tb;ret.push((acc>>bits)&maxv);}}if(pad&&bits)ret.push((acc<<(tb-bits))&maxv);return ret;}
function encode(hrp,ver,prog,bech32m){const data=[ver].concat(conv(prog,8,5,true));const base=expand(hrp).concat(data);const c=bech32m?0x2bc830a3:1;const pm=polymod(base.concat([0,0,0,0,0,0]))^c;const chk=[];for(let i=0;i<6;i++)chk.push((pm>>(5*(5-i)))&31);return hrp+'1'+data.concat(chk).map(x=>CS[x]).join('');}
const rnd=n=>Math.floor(Math.random()*n);
const hrps=['bc','tb','bcrt','ltc','tltc','xyz','a','abcdef'];
const cases=[];
for(let i=0;i<400;i++){
  const hrp=hrps[rnd(hrps.length)],ver=rnd(17),len=2+rnd(39);
  const prog=Array.from({length:len},()=>rnd(256));
  let addr=encode(hrp,ver,prog,Math.random()<0.5);
  const m=rnd(6);
  if(m===0){const p=3+rnd(addr.length-3);const ch=CS[rnd(32)];addr=addr.slice(0,p)+(addr[p]===ch?'q':ch)+addr.slice(p+1);} // corrupt
  if(m===1)addr=addr.toUpperCase();
  if(m===2){const p=rnd(addr.length);addr=addr.slice(0,p)+addr[p].toUpperCase()+addr.slice(p+1);} // mixed case
  if(m===3)addr=addr+'q'.repeat(rnd(80)); // possibly too long
  const q=Math.random();
  const argHrp=q<0.7?hrp:hrps[rnd(hrps.length)];
  cases.push([argHrp,addr]);
}
import {writeFileSync} from 'node:fs';
writeFileSync('/tmp/cases.txt',cases.map(c=>c[0]+'\t'+c[1]).join('\n'));
console.log('generated',cases.length);
EOF
node /tmp/fuzz.mjs

